    {"rule_id": "REG-001", "rule_name": "Statutory Registers Incomplete", "rule_type": "THRESHOLD", "statutory_basis": "Section 34, Companies Act 1994 (Bangladesh)", "description": "One or more of 7 mandatory statutory registers not maintained at registered office. Required: Members (Sec 34), Directors (Sec 90), Charges (Sec 87), Transfers (Sec 108), Debentures (Sec 90), AGM Minutes (Sec 83), Board Minutes (Sec 90). Failure is criminal offence; officers personally liable.", "rule_condition": {"check_fn": "check_reg_001", "trigger": "len(maintained_registers) < 7", "data_points": ["maintained_registers"]}, "default_severity": "NOT_EVALUATED", "score_impact": 0, "revenue_tier": "COMPLIANCE_PACKAGE", "is_black_override": False},
    {"rule_id": "REG-002", "rule_name": "Core Statutory Registers Missing", "rule_type": "THRESHOLD", "statutory_basis": "Sections 34, 89, 115, 174, Companies Act 1994 (Bangladesh)", "description": "Core statutory records missing. Distinguishes (1) internal register-keeping obligations — Members (Sec 34), Meeting minutes (Sec 89), Charges register (Sec 174) — from (2) RJSC filing obligations such as director particulars (Sec 115). Each missing item is an independent legal obligation. Absence of internal registers is a governance failure; missing RJSC filings are separate filing defaults.", "rule_condition": {"check_fn": "check_reg_002", "trigger": "members_register_missing OR directors_register_missing OR charges_register_missing OR minutes_agm_missing OR related RJSC filing gaps", "data_points": ["register_of_members_maintained", "register_of_directors_maintained", "register_of_charges_maintained", "minutes_book_agm_maintained"]}, "default_severity": "NOT_EVALUATED", "score_impact": 0, "revenue_tier": "STRUCTURED_REGULARIZATION", "is_black_override": False},
    {"rule_id": "REG-003", "rule_name": "Registers Not Kept at Registered Office", "rule_type": "THRESHOLD", "statutory_basis": "Section 34(2), Companies Act 1994 (Bangladesh)", "description": "Statutory registers not at registered office. Section 34(2): registers must be at registered office unless RJSC notified of alternative location. Alternative must be in Bangladesh and Board-approved. Registers open to inspection during business hours.", "rule_condition": {"check_fn": "check_reg_003", "trigger": "register_location != registered_office AND alternative_location_notified == False", "data_points": ["register_location", "alternative_location_notified"]}, "default_severity": "NOT_EVALUATED", "score_impact": 0, "revenue_tier": "COMPLIANCE_PACKAGE", "is_black_override": False},

    # MODULE 8: REGISTERED OFFICE — 1 rule (Sec 77, Form VI, 28 days)
    {"rule_id": "OFF-001", "rule_name": "Change of Registered Office Not Filed Within 28 Days", "rule_type": "DEADLINE", "statutory_basis": "Section 77, Companies Act 1994 (Bangladesh)", "description": "Office change not filed via Form VI within 28 days. Section 77 requires 28-day filing (NOT 30 days). Until filed, old address remains legal registered office. Statutory notices served there are valid.", "rule_condition": {"check_fn": "check_off_001", "trigger": "registered_office_change_date IS NOT NULL AND form_vi_filed == False AND days_since_office_change > 28", "data_points": ["registered_office_change_date", "form_vi_filed"]}, "default_severity": "NOT_EVALUATED", "score_impact": 0, "revenue_tier": "COMPLIANCE_PACKAGE", "is_black_override": False},

    # MODULE 9: CAPITAL & CHARGES — 4 rules (Sec 54, 87, 52)
    {"rule_id": "CAP-001", "rule_name": "Capital Alteration Without Proper Resolution", "rule_type": "CASCADE", "statutory_basis": "Sections 53, 54 and 56, Companies Act 1994 (Bangladesh)", "description": "Verify the specific alteration type and Articles authority under section 53. Section 54 addresses specified consolidation/conversion/subdivision notices; increase of registered share capital is separately governed by section 56. Do not assume a special resolution without checking the Act and Articles.", "rule_condition": {"check_fn": "check_cap_001", "trigger": "capital_increase_date IS NOT NULL AND capital_increase_resolution == False", "data_points": ["capital_increase_date", "capital_increase_resolution"]}, "default_severity": "NOT_EVALUATED", "score_impact": 0, "revenue_tier": "COMPLIANCE_PACKAGE", "is_black_override": False},
    {"rule_id": "CAP-002", "rule_name": "Charge Not Registered With RJSC Within 21 Days", "rule_type": "DEADLINE", "statutory_basis": "Section 159(1), Companies Act 1994 (Bangladesh)", "description": "Charge created but not registered via Form XVIII within 21 days under Section 159. Assess the charge instrument, date of creation, registrability, any statutory extension and RJSC certificate; do not infer all consequences from a missing upload.", "rule_condition": {"check_fn": "check_cap_002", "trigger": "charge_creation_date IS NOT NULL AND form_xviii_filed == False AND days_since_charge_creation > 21", "data_points": ["charge_creation_date", "form_xviii_filed"]}, "default_severity": "NOT_EVALUATED", "score_impact": 0, "revenue_tier": "COMPLIANCE_PACKAGE", "is_black_override": False},
    {"rule_id": "CAP-003", "rule_name": "Capital Reduction — Court Confirmation Review", "rule_type": "CASCADE", "statutory_basis": "Sections 59-60, Companies Act 1994 (Bangladesh)", "description": "A pending capital-reduction workflow without verified court-confirmation evidence requires lawyer review. A pending workflow alone does not prove an unlawful completed reduction.", "rule_condition": {"check_fn": "check_cap_003", "trigger": "capital_reduction_pending == True AND capital_reduction_court_order_obtained == False", "data_points": ["capital_reduction_pending", "capital_reduction_court_order_obtained"]}, "default_severity": "NOT_EVALUATED", "score_impact": 0, "revenue_tier": "COMPLIANCE_PACKAGE", "is_black_override": False},
    {"rule_id": "CAP-004", "rule_name": "Special Resolution Not Filed With RJSC", "rule_type": "DEADLINE", "statutory_basis": "Section 88(1), Companies Act 1994 (Bangladesh) — 15 days", "description": "Copy of a special or extraordinary resolution must be filed with RJSC within 15 days under Section 88(1). This filing duty does not by itself determine whether every underlying transaction is valid or complete.", "rule_condition": {"check_fn": "check_cap_004", "trigger": "special_resolution_date IS NOT NULL AND form_viii_filed == False AND days_since_resolution > 15", "data_points": ["special_resolution_date", "form_viii_filed"]}, "default_severity": "NOT_EVALUATED", "score_impact": 0, "revenue_tier": "COMPLIANCE_PACKAGE", "is_black_override": False},

    # MODULE 10: TAX — 2 rules (Income Tax Act 2023, VAT Act 2012)
    {"rule_id": "TAX-001", "rule_name": "TIN Status Requires Verification", "rule_type": "THRESHOLD", "statutory_basis": "Income Tax Act 2023, sections 166, 261 and 264; company-specific duty and evidence require verification", "description": "Review prompt only: verify legal entity and taxpayer identity, return-filing duty under section 166, registration under section 261 and any proof-of-return requirement under section 264. A profile boolean is not authenticated evidence of a breach.", "rule_condition": {"check_fn": "check_tax_001", "trigger": "tin_obtained == False", "data_points": ["tin_obtained", "tin_number"]}, "default_severity": "NOT_EVALUATED", "score_impact": 0, "revenue_tier": "STRUCTURED_REGULARIZATION", "is_black_override": False},
    {"rule_id": "TAX-002", "rule_name": "VAT Registration or Turnover-Tax Enlistment Status Requires Verification", "rule_type": "CONDITIONAL", "statutory_basis": "Value Added Tax and Supplementary Duty Act 2012, sections 2(48), 2(57), 4 and 10, as amended by Act No. 77 of 2026 and Finance Act No. 96 of 2026; exact current section and taxpayer-specific instruments require counsel verification", "description": "Review prompt only. Verify rolling 12-month taxable turnover, mandatory-registration categories and taxpayer activity. Above BDT 30 lakh up to BDT 50 lakh may require turnover-tax enlistment; above BDT 50 lakh may require VAT registration. Verify the 30-day application period and effective date before any breach finding.", "rule_condition": {"check_fn": "check_tax_002", "trigger": "vat_registered == False AND reported_annual_turnover_bdt > 3000000", "data_points": ["vat_registered", "annual_turnover_bdt"], "conditional": True}, "default_severity": "NOT_EVALUATED", "score_impact": 0, "revenue_tier": "COMPLIANCE_PACKAGE", "is_black_override": False},

    # MODULE 11: ESCALATION — review-only Registrar process (Section 346)
    {"rule_id": "ESC-001", "rule_name": "Strike-Off Process Status Requires Verification", "rule_type": "ESCALATION", "statutory_basis": "Section 346, Companies Act 1994 (Bangladesh); Registrar process and case-specific evidence required", "description": "Review prompt only: multi-year backlog is an internal escalation indicator, not proof that RJSC commenced strike-off. Verify statutory grounds, Registrar notice, service, procedural stage, appeal, restoration and current company status.", "rule_condition": {"check_fn": "check_esc_001", "trigger": "unfiled_returns_count >= 2 OR (active_red_flags >= 3 AND active_yellow_flags >= 4)", "data_points": ["unfiled_returns_count", "active_red_flags", "active_yellow_flags"]}, "default_severity": "NOT_EVALUATED", "score_impact": 0, "revenue_tier": "COMPLIANCE_PACKAGE", "is_black_override": False},
    {"rule_id": "ESC-002", "rule_name": "Strike-Off Status Requires Verification", "rule_type": "ESCALATION", "statutory_basis": "Section 346, Companies Act 1994 (Bangladesh); Registrar process and case-specific evidence required", "description": "Review prompt only: verify the statutory grounds, Registrar notice, service, procedural stage, appeal, restoration and current register status. A filing backlog or unverified list indicator is not proof that strike-off is imminent or has occurred.", "rule_condition": {"check_fn": "check_esc_002", "trigger": "unfiled_returns_count >= 3 OR rjsc_strike_off_notice_date IS NOT NULL OR on_rjsc_strike_off_list == True", "data_points": ["unfiled_returns_count", "rjsc_strike_off_notice_date", "on_rjsc_strike_off_list"]}, "default_severity": "NOT_EVALUATED", "score_impact": 0, "revenue_tier": "COMPLIANCE_PACKAGE", "is_black_override": False},
    {"rule_id": "ESC-003", "rule_name": "Corporate Rescue Mandatory — Systemic Failure", "rule_type": "ESCALATION", "statutory_basis": "NLC internal risk policy; not a statutory risk band under the Companies Act 1994.", "description": "Internal BLACK escalation and rescue workflow. A BLACK classification, score threshold and rescue deadline are NLC policy decisions, not statutory consequences. Policy-owner approval is required.", "rule_condition": {"check_fn": "check_esc_003", "trigger": "pre_override_score <= 29 OR has_black_override == True", "data_points": ["pre_override_score", "has_black_override", "active_red_flags", "active_black_flags"]}, "default_severity": "NOT_EVALUATED", "score_impact": 0, "revenue_tier": "CORPORATE_RESCUE", "is_black_override": False},
    # ═══════════════════════════════════════════════════════════════
    # EXTENDED RULES (synced from engine.py – 29 rules previously missing)
    # ═══════════════════════════════════════════════════════════════

    {"rule_id": "AGM-007", "rule_name": "AGM Adjournment Notice Requires Review", "rule_type": "THRESHOLD", "statutory_basis": "Companies Act 1994, Section 85 and the company Articles; exact adjournment provision requires counsel verification", "description": "Review prompt only: verify the applicable Articles, meeting resolution, adjournment terms, notice method and exact statutory consequence before classifying a breach.", "rule_condition": {"check_fn": "check_agm_007", "trigger": "agm_adjourned_without_notice == True", "data_points": ["agm_adjourned_without_notice"]}, "default_severity": "NOT_EVALUATED", "score_impact": 0, "revenue_tier": "COMPLIANCE_PACKAGE", "is_black_override": False},
    {"rule_id": "AUD-005", "rule_name": "Subsequent Auditor Reappointment Status Unknown", "rule_type": "DEPENDENCY", "statutory_basis": "Section 210(3), Companies Act 1994 (Bangladesh)", "description": "No verified record establishes whether the retiring auditor was reappointed or a statutory exception applied. Evidence-status only; no 120-day deadline.", "rule_condition": {"check_fn": "check_aud_005", "trigger": "agm_held_this_cycle == True AND auditor_reappointed_at_agm IS NULL", "data_points": ["agm_held_this_cycle", "auditor_reappointed_at_agm"]}, "default_severity": "NOT_EVALUATED", "score_impact": 0, "revenue_tier": "COMPLIANCE_PACKAGE", "is_black_override": False},
    {"rule_id": "BNK-001", "rule_name": "Winding Up Petition Filed", "rule_type": "THRESHOLD", "statutory_basis": "Companies Act 1994 (Bangladesh), Part V, sections 241–244; exact petition provision requires case review", "description": "Reported company winding-up petition. Verify the Companies Act petition, grounds, court, case number, service, current status, withdrawal/dismissal/stay and authenticated court record. Do not conflate corporate winding-up with personal bankruptcy.", "rule_condition": {"check_fn": "check_bnk_001", "trigger": "winding_up_petition_filed == True", "data_points": ["winding_up_petition_filed"]}, "default_severity": "NOT_EVALUATED", "score_impact": 0, "revenue_tier": "CORPORATE_RESCUE", "is_black_override": False},
    {"rule_id": "BNK-002", "rule_name": "Liquidator Appointed", "rule_type": "THRESHOLD", "statutory_basis": "Companies Act 1994 (Bangladesh), Part V; section 255 for court-appointed Official Liquidators; route-specific provision requires review", "description": "Reported liquidator appointment. Verify whether the appointment arises from a court winding-up order, voluntary winding-up or another statutory route; obtain the appointment instrument and confirm the appointee’s authority and current status.", "rule_condition": {"check_fn": "check_bnk_002", "trigger": "liquidator_appointed == True", "data_points": ["liquidator_appointed"]}, "default_severity": "NOT_EVALUATED", "score_impact": 0, "revenue_tier": "CORPORATE_RESCUE", "is_black_override": False},
    {"rule_id": "BNK-003", "rule_name": "Court-Ordered Winding Up", "rule_type": "THRESHOLD", "statutory_basis": "Companies Act 1994 (Bangladesh), Part V, sections 241–246; exact order provision requires case review", "description": "Reported court winding-up order. Verify the authenticated order, operative date, court jurisdiction, appeal/stay, correction, suspension or discharge, and current liquidation status.", "rule_condition": {"check_fn": "check_bnk_003", "trigger": "court_ordered_winding_up == True", "data_points": ["court_ordered_winding_up"]}, "default_severity": "NOT_EVALUATED", "score_impact": 0, "revenue_tier": "CORPORATE_RESCUE", "is_black_override": False},
    {"rule_id": "BSEC-001", "rule_name": "Quarterly Report Status Requires Verification", "rule_type": "DEADLINE", "statutory_basis": "Applicable BSEC financial-reporting instrument; exact notification, issuer class, reporting period and due date require verification", "description": "Review prompt only: verify the exact BSEC financial-reporting instrument, listed issuer class, reporting period and due date; this is not Corporate Governance Code Condition 8.", "rule_condition": {"check_fn": "check_bsec_001", "trigger": "bsec_listed == True AND bsec_quarterly_report_filed == False", "data_points": ["bsec_listed", "bsec_quarterly_report_filed"], "conditional": True}, "default_severity": "NOT_EVALUATED", "score_impact": 0, "revenue_tier": "STRUCTURED_REGULARIZATION", "is_black_override": False},
    {"rule_id": "BSEC-002", "rule_name": "CG Certificate Status Requires Verification", "rule_type": "THRESHOLD", "statutory_basis": "BSEC Corporate Governance Code 2018, as amended by applicable 2023 and 2024 notifications; exact condition-specific applicability and evidence require verification", "description": "Review prompt only: Condition 9 requires annual corporate-governance compliance certification by a practicing professional accountant or secretary other than the statutory auditor, with disclosure in the annual report. Verify listed-issuer scope, certifier eligibility, AGM appointment and evidence.", "rule_condition": {"check_fn": "check_bsec_002", "trigger": "bsec_listed == True AND cg_certificate_obtained == False", "data_points": ["bsec_listed", "cg_certificate_obtained"], "conditional": True}, "default_severity": "NOT_EVALUATED", "score_impact": 0, "revenue_tier": "STRUCTURED_REGULARIZATION", "is_black_override": False},
    {"rule_id": "BSEC-003", "rule_name": "Board Composition Status Requires Verification", "rule_type": "THRESHOLD", "statutory_basis": "BSEC Corporate Governance Code 2018, as amended by applicable 2023 and 2024 notifications; exact condition-specific applicability and evidence require verification", "description": "Review prompt only: verify Condition 1 board size, independent-director ratio, eligibility and appointment process. The 2024 amendment adds at least one female independent director; BSEC's 26 July 2026 register lists a further extension, reported to 31 December 2026. Verify the original notice and any later direction before applying a deadline.", "rule_condition": {"check_fn": "check_bsec_003", "trigger": "bsec_listed == True AND board_independent_director == False", "data_points": ["bsec_listed", "board_independent_director"], "conditional": True}, "default_severity": "NOT_EVALUATED", "score_impact": 0, "revenue_tier": "COMPLIANCE_PACKAGE", "is_black_override": False},
    {"rule_id": "BSEC-004", "rule_name": "Audit Committee Status Requires Verification", "rule_type": "THRESHOLD", "statutory_basis": "BSEC Corporate Governance Code 2018, as amended by applicable 2023 and 2024 notifications; exact condition-specific applicability and evidence require verification", "description": "Review prompt only: verify Condition 5 audit committee composition, independent director, financial literacy, quorum, meetings, duties and listed-issuer scope. Do not infer non-compliance from a single profile boolean.", "rule_condition": {"check_fn": "check_bsec_004", "trigger": "bsec_listed == True AND audit_committee_established == False", "data_points": ["bsec_listed", "audit_committee_established"], "conditional": True}, "default_severity": "NOT_EVALUATED", "score_impact": 0, "revenue_tier": "COMPLIANCE_PACKAGE", "is_black_override": False},
    {"rule_id": "CHG-001", "rule_name": "Charge Satisfaction — Evidence Review Required", "rule_type": "DEADLINE", "statutory_basis": "Section 172(1), read with Section 159, Companies Act 1994 (Bangladesh)", "description": "Review-only. Confirm that the charge is registrable under s.159, authenticate satisfaction and its date, and verify RJSC filing status before assessing the 21-day s.172(1) duty. Missing evidence is UNKNOWN, not proof of non-filing.", "rule_condition": {"check_fn": "check_chg_001", "trigger": "verified charge.satisfied == True AND verified registrable_under_s159 == True AND verified satisfaction_filed == False AND satisfaction_date + 21 days < today", "data_points": ["charges", "registrability_evidence_ref", "satisfaction_evidence_ref", "satisfaction_filing_evidence_ref"]}, "default_severity": "NOT_EVALUATED", "score_impact": 0, "revenue_tier": "COMPLIANCE_PACKAGE", "is_black_override": False},
    {"rule_id": "DEF-001", "rule_name": "Director Disqualified", "rule_type": "THRESHOLD", "statutory_basis": "Section 94, Companies Act 1994 (Bangladesh)", "description": "Director disqualification requires a specified Section 94 or Articles ground, director identity, authoritative evidence, effective date and continuing status. Unpaid-call ground remains DISPUTED: official Bengali text says 180 days, while English/case materials say six months. Do not automatically classify until a Bangladesh company-law reviewer resolves the discrepancy. Section 94 does not prescribe a universal five-year ban. This finding is not an automatic BLACK override and remains outside production scoring pending independent legal approval.", "rule_condition": {"check_fn": "check_def_001", "trigger": "structured verified disqualification_grounds with all required evidence fields", "data_points": ["disqualification_grounds", "director_name", "evidence_ref", "authority", "effective_date", "continuing_status"]}, "default_severity": "NOT_EVALUATED", "score_impact": 0, "revenue_tier": "STRUCTURED_REGULARIZATION", "is_black_override": False},
    {"rule_id": "DEF-002", "rule_name": "Unresolved Penalty Notices", "rule_type": "ESCALATION", "statutory_basis": "Case-specific enabling provision required; not a universal section", "description": "Review prompt only: each penalty/prosecution notice must be matched to its enabling provision, issuing authority, service, response deadline, appeal/stay and current disposition. No universal Companies Act penalty provision is assumed.", "rule_condition": {"check_fn": "check_def_002", "trigger": "penalty_notices_received > penalty_notices_resolved", "data_points": ["penalty_notices_received", "penalty_notices_resolved"]}, "default_severity": "NOT_EVALUATED", "score_impact": 0, "revenue_tier": "STRUCTURED_REGULARIZATION", "is_black_override": False},
    {"rule_id": "DIR-005", "rule_name": "Director Interest Disclosure/Register Requires Review", "rule_type": "THRESHOLD", "statutory_basis": "Companies Act 1994, Section 130 (director-interest disclosure); generic register duty/title requires legal reconciliation", "description": "Review prompt only: Section 130 concerns disclosure of a director's interest in a company contract or arrangement; it does not by itself establish this generic register obligation. Verify the actual duty, Articles and documentary evidence.", "rule_condition": {"check_fn": "check_dir_005", "trigger": "register_of_directors_interests == False", "data_points": ["register_of_directors_interests"]}, "default_severity": "NOT_EVALUATED", "score_impact": 0, "revenue_tier": "COMPLIANCE_PACKAGE", "is_black_override": False},
    {"rule_id": "DIR-006", "rule_name": "Register of Contracts Requires Review", "rule_type": "THRESHOLD", "statutory_basis": "Companies Act 1994 and applicable Articles; exact register obligation requires counsel verification", "description": "Review prompt only: no universal register-of-contracts duty has been established for this generic rule. Verify the exact statutory provision, company Articles, contract category and evidence.", "rule_condition": {"check_fn": "check_dir_006", "trigger": "register_of_contracts == False", "data_points": ["register_of_contracts"]}, "default_severity": "NOT_EVALUATED", "score_impact": 0, "revenue_tier": "COMPLIANCE_PACKAGE", "is_black_override": False},
    {"rule_id": "ESC-004", "rule_name": "Voluntary Winding Up", "rule_type": "THRESHOLD", "statutory_basis": "Section 286, Companies Act 1994 (Bangladesh)", "description": "Reported voluntary winding-up resolution. Verify the statutory ground, resolution, applicable solvency declaration, liquidator appointment, creditor process and current status under Part V; no automatic BLACK classification.", "rule_condition": {"check_fn": "check_esc_004", "trigger": "voluntary_winding_up == True", "data_points": ["voluntary_winding_up"]}, "default_severity": "NOT_EVALUATED", "score_impact": 0, "revenue_tier": "CORPORATE_RESCUE", "is_black_override": False},
    {"rule_id": "ESC-005", "rule_name": "Investigation Order Pending", "rule_type": "THRESHOLD", "statutory_basis": "Sections 195 and 197; section 199 where related entities are included, Companies Act 1994 (Bangladesh)", "description": "Reported company investigation. Verify the Government inspector appointment under section 195 or 197, the scope of any section 199 related-entity investigation, authenticated order, parties and current status. An inquiry is not itself a finding of liability.", "rule_condition": {"check_fn": "check_esc_005", "trigger": "investigation_order == True", "data_points": ["investigation_order"]}, "default_severity": "NOT_EVALUATED", "score_impact": 0, "revenue_tier": "STRUCTURED_REGULARIZATION", "is_black_override": False},
    {"rule_id": "FX-001", "rule_name": "Foreign Exchange Violation", "rule_type": "THRESHOLD", "statutory_basis": "Foreign Exchange Regulation Act 1947 (Bangladesh)", "description": "Foreign exchange violation detected under FE Regulation Act 1947.", "rule_condition": {"check_fn": "check_fx_001", "trigger": "foreign_exchange_violation == True", "data_points": ["foreign_exchange_violation"]}, "default_severity": "NOT_EVALUATED", "score_impact": 0, "revenue_tier": "STRUCTURED_REGULARIZATION", "is_black_override": False},
    {"rule_id": "LBR-001", "rule_name": "Factory License Missing", "rule_type": "THRESHOLD", "statutory_basis": "Bangladesh Labour Act 2006, Section 326, as amended by Act No. 43 of 2026", "description": "Review prompt only: verify a Government direction under section 326, establishment class, effective date, exemptions and authentic licence status.", "rule_condition": {"check_fn": "check_lbr_001", "trigger": "factory_license_required_by_direction == True AND factory_license_obtained == False", "data_points": ["factory_license_obtained"]}, "default_severity": "NOT_EVALUATED", "score_impact": 0, "revenue_tier": "STRUCTURED_REGULARIZATION", "is_black_override": False},
    {"rule_id": "LBR-002", "rule_name": "Factory License Expired", "rule_type": "DEADLINE", "statutory_basis": "Bangladesh Labour Act 2006, Section 326, as amended by Act No. 43 of 2026", "description": "Review prompt only: verify the section 326 Government direction, licence class, five-year/contractor one-year term, renewal application and any extension.", "rule_condition": {"check_fn": "check_lbr_002", "trigger": "factory_license_required_by_direction == True AND factory_license_expiry < today", "data_points": ["factory_license_expiry"]}, "default_severity": "NOT_EVALUATED", "score_impact": 0, "revenue_tier": "COMPLIANCE_PACKAGE", "is_black_override": False},
    {"rule_id": "LBR-003", "rule_name": "Labour Court Order Pending", "rule_type": "THRESHOLD", "statutory_basis": "Bangladesh Labour Act 2006 and the specific Labour Court order; enabling provision and operative status require case-specific verification", "description": "Review prompt only: verify certified order, parties, company identity, service, operative directions, appeal/revision and stay before finding non-compliance.", "rule_condition": {"check_fn": "check_lbr_003", "trigger": "labour_court_order_pending == True", "data_points": ["labour_court_order_pending"]}, "default_severity": "NOT_EVALUATED", "score_impact": 0, "revenue_tier": "STRUCTURED_REGULARIZATION", "is_black_override": False},
