EXPECTED_RULE_COUNT = 85


def get_database_url() -> str:
    url = os.environ.get("DATABASE_URL", "")
    if not url:
        raise RuntimeError("DATABASE_URL not set. Export DATABASE_URL=postgresql+asyncpg://...")
    if url.startswith("postgresql://"):
        url = url.replace("postgresql://", "postgresql+asyncpg://", 1)
    if url.startswith("postgres://"):
        url = url.replace("postgres://", "postgresql+asyncpg://", 1)
    return url


async def seed_rules(dry_run: bool = True, verbose: bool = False) -> int:
    print(f"\n{'='*60}")
    print(f" NEUM LEX COUNSEL — Legal Rules Seeder v2.0")
    print(f" ILRMF — {EXPECTED_RULE_COUNT} rules")
    print(f" Mode: {'DRY RUN' if dry_run else 'LIVE'}")
    print(f"{'='*60}\n")

    valid_types = {"AGM", "AUDIT", "RETURN", "DIRECTOR", "TRANSFER", "REGISTER",
                   "ESCALATION", "CASCADE", "DEADLINE", "DEPENDENCY", "THRESHOLD", "CONDITIONAL"}
    valid_sev = {"GREEN", "YELLOW", "RED", "BLACK", "NOT_EVALUATED"}
    valid_tier = {"COMPLIANCE_PACKAGE", "STRUCTURED_REGULARIZATION", "CORPORATE_RESCUE"}

    print("Validating...")
    seen = set()
    for rule in ILRMF_RULES:
        issues = []
        if rule["rule_id"] in seen:
            issues.append("duplicate")
        seen.add(rule["rule_id"])
        if rule["rule_type"] not in valid_types:
            issues.append(f"bad type: {rule['rule_type']}")
        if rule["default_severity"] not in valid_sev:
            issues.append(f"bad severity: {rule['default_severity']}")
        if rule["revenue_tier"] not in valid_tier:
            issues.append(f"bad tier: {rule['revenue_tier']}")
        if rule["is_black_override"] and rule["default_severity"] != "BLACK":
            issues.append("override=True but severity!=BLACK")
        if issues:
            raise ValueError(f"{rule['rule_id']}: {', '.join(issues)}")
        if verbose:
            print(f"  {rule['rule_id']:10s} {rule['default_severity']:7s} {rule['score_impact']:2d}pts {rule['rule_name'][:50]}")

    if len(ILRMF_RULES) != EXPECTED_RULE_COUNT:
        raise ValueError(f"Expected {EXPECTED_RULE_COUNT}, got {len(ILRMF_RULES)}")
    print(f"\n  All {len(ILRMF_RULES)} rules valid\n")

    if dry_run:
        from collections import Counter
        mods = Counter(r["rule_id"].split("-")[0] for r in ILRMF_RULES)
        print("Module summary:")
        for m, cnt in sorted(mods.items()):
            print(f"  {m:6s}: {cnt} rules")
        blacks = [r["rule_id"] for r in ILRMF_RULES if r["is_black_override"]]
        print(f"\nBLACK overrides ({len(blacks)}): {', '.join(blacks)}")
        print(f"Max deduction: {sum(r['score_impact'] for r in ILRMF_RULES)} pts")
        print("\nDry run complete.")
        return 0

    db_url = get_database_url()
    engine = create_async_engine(db_url, echo=False)

    async with engine.begin() as conn:
        inserted = unchanged = drift = 0
        drifted_rules: list[str] = []
        now = datetime.now(UTC)

        for rule in ILRMF_RULES:
            res = await conn.execute(
                sa.text("""
                    SELECT id, rule_name, rule_type, statutory_basis, description,
                           rule_condition, default_severity::text AS default_severity,
                           score_impact, revenue_tier::text AS revenue_tier, is_black_override
                    FROM legal_rules WHERE rule_id = :rid
                """),
                {"rid": rule["rule_id"]}
            )
            existing = res.fetchone()

            if existing:
                actual = dict(existing._mapping)
                expected = {
                    "rule_name": rule["rule_name"],
                    "rule_type": rule["rule_type"],
                    "statutory_basis": rule["statutory_basis"],
                    "description": rule["description"],
                    "rule_condition": rule["rule_condition"],
                    "default_severity": rule["default_severity"],
                    "score_impact": rule["score_impact"],
                    "revenue_tier": rule["revenue_tier"],
                    "is_black_override": rule["is_black_override"],
                }
                differences = []
                for key, expected_value in expected.items():
                    actual_value = actual.get(key)
                    if hasattr(actual_value, "value"):
                        actual_value = actual_value.value
                    if key == "rule_condition" and isinstance(actual_value, str):
                        actual_value = json.loads(actual_value)
                    if actual_value != expected_value:
                        differences.append(key)
                if differences:
                    drift += 1
                    drifted_rules.append(f"{rule['rule_id']} ({', '.join(differences)})")
                    status = "DRIFT"
                else:
                    unchanged += 1
                    status = "unchanged"
            else:
                await conn.execute(sa.text("""
                    INSERT INTO legal_rules (
                        id, rule_id, rule_name, rule_type, statutory_basis,
                        description, rule_condition, default_severity, score_impact,
                        revenue_tier, is_black_override, rule_version, is_active,
                        created_at, updated_at
                    ) VALUES (
                        uuid_generate_v4(), :rid, :rn, :rt, :sb,
                        :desc, CAST(:rc AS jsonb), CAST(:ds AS severity_level), :si,
                        CAST(:rev AS revenue_tier), :ibo, '2.0', TRUE, :now, :now
                    )
                """), {
                    "rid": rule["rule_id"], "rn": rule["rule_name"], "rt": rule["rule_type"],
                    "sb": rule["statutory_basis"], "desc": rule["description"],
                    "rc": json.dumps(rule["rule_condition"]), "ds": rule["default_severity"],
                    "si": rule["score_impact"], "rev": rule["revenue_tier"],
                    "ibo": rule["is_black_override"], "now": now,
                })
                inserted += 1
                status = "inserted"

            if verbose:
                print(f"  {status:8s} {rule['rule_id']:10s} {rule['default_severity']:7s} {rule['score_impact']:2d}pts")

        if drifted_rules:
            # Existing rows are intentionally left untouched. Missing rows
            # may still be inserted, but every drift item must be reconciled
            # through the authenticated RulesService workflow with a
            # change_reason and immutable LegalRuleVersion snapshot.
            print(" WARNING: existing rule definitions differ; no existing row was updated.")
            for item in drifted_rules:
                print(f"   DRIFT: {item}")

        ids_result = await conn.execute(
            sa.text("SELECT rule_id FROM legal_rules WHERE is_active = TRUE")
        )
        active_ids = {row[0] for row in ids_result.fetchall()}
        expected_ids = {rule["rule_id"] for rule in SEED_RULES}
        db_count = len(active_ids)
        missing_ids = sorted(expected_ids - active_ids)
        extra_ids = sorted(active_ids - expected_ids)
        await engine.dispose()

        print(f"\n{'='*60}")
        print(f" Done! Inserted: {inserted}, Existing unchanged: {unchanged}, Drift: {drift}")
        print(f" DB active rules: {db_count} (seed expects {EXPECTED_RULE_COUNT})")
        if missing_ids:
            print("  Missing rule IDs: " + ", ".join(missing_ids))
        if extra_ids:
            print("  Extra active rule IDs (do not delete automatically): " + ", ".join(extra_ids))
        if drifted_rules:
            print("  Existing definition drift requires the audited Super Admin workflow.")
        print(f"{'='*60}\n")
        return inserted


def main():
    p = argparse.ArgumentParser(description="Seed ILRMF 85-rule corpus (dry-run by default)")
    p.add_argument(
        "--apply",
        action="store_true",
        help="Insert missing rules only; existing rule changes require the audited Super Admin workflow",
    )
    p.add_argument("--verbose", "-v", action="store_true")
    args = p.parse_args()
    try:
        asyncio.run(seed_rules(dry_run=not args.apply, verbose=args.verbose))
    except Exception as e:
        print(f"\nFAILED: {e}", file=sys.stderr)
        sys.exit(1)


if __name__ == "__main__":
    main()
